parameters.jsCode:
// Extract data from webhook body
const body = $input.first().json.body;

const { guild_id, discord_user_id, remaining, quota } = body;
const percentage = Math.round((remaining / quota) * 100);

return {
  guild_id,
  discord_user_id,
  remaining,
  quota,
  percentage,
  alert_type: 'low_credits'
};

